#include <item/DungeonItems.hpp>
#include <item/NativeMoney.hpp>
void DungeonUseCatalogWorker(const GameSqlConfig& player,const std::shared_ptr<const auriga::item::ItemCatalog>& catalog,const std::string& password,const std::string& path,const std::vector<BulkSource>& sources){
 using namespace auriga::item;Check(sources.size()==12,"all twelve authored original dungeon-use definitions");
 CAsyncSQL sql;sql.SetTimeouts(5);sql.SetRetryConnectionErrors(false);Check(sql.Setup("127.0.0.1","root",password.c_str(),"player","utf8mb4",true,player.port),"owned dungeon-use SQL connection");
 auto& store=runtime::ItemStore::Instance();Check(store.Start(player,catalog,"source-dungeon-use-worker").has_value(),"actual dungeon-use item worker starts");
 unsigned serial=0,packets=0;bool replay=false;auto op=[&](){++serial;return std::array<std::uint8_t,16>{0x59,static_cast<std::uint8_t>(serial),static_cast<std::uint8_t>(serial>>8)};};
 auto apply=[&](persistence::LoadedItemOwner& state,const ItemCommit& commit){std::optional<runtime::CommitOutcome> out;Check(runtime::RequestCommit(state.fence.owner,state.fence.sessionGeneration,commit,[&](auto result){out=std::move(result);}),"stage item operation queued");for(unsigned n=0;!out&&n<2000;++n){store.Drain();std::this_thread::sleep_for(std::chrono::milliseconds(5));}Check(out&&out->write&&out->state,"stage item SQL write confirmed");replay=out->write->replay;if(!replay)runtime::SpendInstanceIds(std::ranges::count_if(commit.items,[](const auto& change){return !change.before;}));state=std::move(*out->state);};
 for(unsigned n=0;n<sources.size();++n){const ItemOwner owner{ItemOwnerKind::Character,26001u+n};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,4}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,{}).has_value(),"native dungeon-use owner provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();
  auto grant=sources[n].grant;grant.count=2;grant.createdAtUtcMs=static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());auto ids=runtime::PeekInstanceIds(4);Check(ids.size()==4,"concrete source IDs allocated");auto granted=MakeGrantCommit(*catalog,op(),state.fence,state.storages,state.items,grant,ids);if(!granted)throw std::runtime_error("Dungeon-use grant source="+std::to_string(n)+" error="+std::to_string(static_cast<unsigned>(granted.error())));apply(state,*granted);const auto id=state.items.front().id;
  const auto role=DungeonItemUseRole(*catalog,grant.key);Check(role!=DungeonUseRole::None,"original source has explicit native semantic role");
  const auto write=[&](const std::string& phase){const auto file=[&](const char* kind,const auto& bytes){std::ofstream f(path+"."+std::to_string(n)+"."+phase+"."+kind+".hex");for(auto b:bytes){const auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';Check(f.good(),"real dungeon-use frame exported");};file("inventory",EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value());file("details",EncodeTypedItemDetails(*catalog,state.items,false,std::array{grant}).value());++packets;};
  write("ready");DungeonUseFacts facts;facts.admitted=facts.stageReady=true;facts.character.level=255;facts.character.nowUtcMs=grant.createdAtUtcMs;const auto* use=catalog->FindUsePolicy(catalog->Find(grant.key)->base.usePolicy);while(!(use->allowedClasses&(1u<<facts.character.characterClass)))++facts.character.characterClass;while(!(use->allowedSexes&(1u<<facts.character.sex)))++facts.character.sex;
  auto denied=facts;denied.stageReady=false;Check(!MakeDungeonUseCommit(*catalog,op(),state.fence,state.storages,state.items,id,denied),"wrong stage or unreachable target spends nothing");auto foreign=state.fence;++foreign.owner.id;Check(!MakeDungeonUseCommit(*catalog,op(),foreign,state.storages,state.items,id,facts),"foreign identity cannot be offered");
  const auto planned=MakeDungeonUseCommit(*catalog,op(),state.fence,state.storages,state.items,id,facts);if(!planned)throw std::runtime_error("Dungeon-use plan source="+std::to_string(n)+" key="+std::to_string(grant.key.LocalId())+" error="+std::to_string(static_cast<unsigned>(planned.error())));const auto commit=*planned;Check(commit.items.size()==1&&commit.result.back()==static_cast<unsigned>(role),"only concrete selected item in authoritative stage debit");apply(state,commit);Check(CountMissionItems(state.items,owner,grant.key,0)==1,"exactly one original item consumed");write("used");auto saved=state.items;apply(state,commit);Check(replay&&state.items==saved,"stage receipt replay cannot spend another unit");write("replayed");
  const auto session=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,session).value();Check(state.items==saved,"stage state persists unchanged through fresh login");write("relogged");
 }
 const ItemOwner owner{ItemOwnerKind::Character,26100};const std::array layouts{ItemStorageLayout{{owner,ItemStorageKind::Inventory,1},5,9,1}};const std::array wallets{ItemWallet{owner,WalletCurrency::Gold,1,7000001001ULL}};Check(persistence::ProvisionOwner(sql,*catalog,owner,layouts,wallets).has_value(),"native quest wallet provisioned");auto state=persistence::LoadCurrentItemOwner(sql,*catalog,owner).value();
 const auto walletOutput=[&](const std::string& phase){const auto raw=EncodeTypedInventory(*catalog,state.storages,state.wallets,state.items).value();std::ofstream f(path+".wallet."+phase+".inventory.hex");for(auto b:raw){const auto v=static_cast<unsigned char>(b);f<<"0123456789abcdef"[v>>4]<<"0123456789abcdef"[v&15];}f<<'\n';std::ofstream facts(path+".wallet."+phase+".json");facts<<"{\"balance\":"<<state.wallets[0].balance<<"}\n";Check(f.good()&&facts.good(),"real quest wallet frames exported");};
 walletOutput("before");const auto debit=MakeQuestGoldChange(*catalog,op(),state.fence,state.wallets[0],-7000000001LL,999000000000ULL).value();apply(state,debit);Check(state.wallets[0].balance==1000,"actual quest debit takes full64-bit amount");walletOutput("paid");apply(state,debit);Check(replay&&state.wallets[0].balance==1000,"quest debit replay cannot pay twice");walletOutput("replayed");Check(!MakeQuestGoldChange(*catalog,op(),state.fence,state.wallets[0],-1001,999000000000ULL),"quest insufficient funds fail before SQL or later reward");
 const auto credit=MakeQuestGoldChange(*catalog,op(),state.fence,state.wallets[0],7000000001LL,999000000000ULL).value();apply(state,credit);Check(state.wallets[0].balance==7000001001ULL,"actual quest reward credits full64-bit amount");walletOutput("reward");const auto generation=persistence::ClaimOwnerSession(sql,*catalog,owner).value();state=persistence::LoadItemOwner(sql,*catalog,owner,generation).value();Check(state.wallets[0].balance==7000001001ULL,"native quest balance survives relog");walletOutput("relogged");
 store.Stop();std::cout<<"SOURCE_DUNGEON_USE_WORKER=SUCCESS sources=12 packets="<<packets<<" checks="<<checks<<std::endl;
}
